  ];
  for (const entry of presets) if (!spawns.manager.getPreset(entry.id)) spawns.debug.addPreset(entry);
  window.__dwEm = {
    engine,
    ids: presets.map((entry) => entry.id),
    /** What dispose must give back: GPU memory, wind sources, sky modifiers and real lights. */
    snapshot() {
      const memory = ctx.renderer.info.memory;
      return {
        geometries: memory.geometries, textures: memory.textures, attributes: memory.attributes,
        wind: ctx.wind.sourceCount, modifiers: ctx.systems.sky.getModifierState().ids.join(','),
        lights: spawns.getStats().lights.active,
      };
    },
    parts: (id) => spawns.manager.getParts(id).map((part) => part.instance ?? part),
    /**
     * Frames a spawn: the craft is moved back metres from it (toward where the craft was), lift
     * metres above the ground, flying across the view; the free camera (which stays within 900 m of
     * the craft) sits there looking at the anchor plus lookUp metres.
     */
    frame(id, { back = 400, lift = 60, lookUp = 0 } = {}) {
      const anchor = spawns.manager.getInstance(id).position;
      const player = game.state.player.position;
      const length = Math.hypot(player.x - anchor.x, player.z - anchor.z) || 1;
      const awayX = (player.x - anchor.x) / length;
      const awayZ = (player.z - anchor.z) / length;
      const x = anchor.x + awayX * back;
      const z = anchor.z + awayZ * back;
      const ground = Math.max(ctx.world.groundHeight(x, z), ctx.world.WATER_LEVEL);
      const y = Math.max(ground, anchor.y) + lift;
      const bearing = ctx.util.bearingTo(x, z, anchor.x, anchor.z);
      ctx.systems.flight.resetTo({ x, y: y - 30, z, heading: bearing + 90 });
      return ctx.systems.camera.setFreeCameraPose({ position: { x, y, z }, target: { x: anchor.x, y: anchor.y + lookUp, z: anchor.z } });
    },
    /**
     * Starts presetId on a site the camera can see whatever the seed: candidate anchors on rings
     * around the craft (from..to metres), each tried from 8 camera bearings back metres away and
     * lift metres above the higher of the two grounds. The lines from the camera to the target
     * (the anchor plus lookUp metres) and to the anchor's base must clear the terrain by 8 m; the
     * flattest clear site wins (dry land, or open water when water is set). The craft is moved under the
     * camera, flying across the view, and the free camera frames the target.
     */
    site(presetId, { from = 400, to = 1600, back = 400, lift = 80, lookUp = 0, water = false } = {}) {
      const player = game.state.player.position;
      const waterLevel = ctx.world.WATER_LEVEL;
      const surface = (x, z) => Math.max(ctx.world.groundHeight(x, z), waterLevel);
      const clearLine = (from3, to3) => {
        for (let step = 1; step < 16; step++) {
          const share = step / 16;
          const y = from3.y + (to3.y - from3.y) * share;
          if (surface(from3.x + (to3.x - from3.x) * share, from3.z + (to3.z - from3.z) * share) > y - 8) return false;
        }
        return true;
      };
      let best = null;
      for (let ring = 0; ring < 5; ring++) {
        const distance = from + ((to - from) * ring) / 4;
        for (let index = 0; index < 16; index++) {
          const angle = (index / 16) * Math.PI * 2;
          const x = player.x + Math.cos(angle) * distance;
          const z = player.z + Math.sin(angle) * distance;
          const ground = ctx.world.groundHeight(x, z);
          const base = Math.max(ground, waterLevel);
          const slope = Math.abs(surface(x + 40, z) - surface(x - 40, z)) + Math.abs(surface(x, z + 40) - surface(x, z - 40));
          const wet = ground < waterLevel - 3;
          const penalty = wet === water ? 0 : 1e6;
          if (best !== null && slope + penalty >= best.score) continue;
          for (let view = 0; view < 8; view++) {
            const bearing = (view / 8) * Math.PI * 2;
            const cameraX = x + Math.cos(bearing) * back;
            const cameraZ = z + Math.sin(bearing) * back;
            const camera = { x: cameraX, y: Math.max(surface(cameraX, cameraZ), base) + lift, z: cameraZ };
            const target = { x, y: base + lookUp, z };
            if (!clearLine(camera, target) || !clearLine(camera, { x, y: base + 4, z })) continue;
            best = { score: slope + penalty, x, z, base, camera, target };
            break;
          }
        }
      }
      if (!best) throw new Error(`no site with a clear view for ${presetId} within ${to} m`);
      const id = spawns.manager.activate(presetId, { position: { x: best.x, y: best.base, z: best.z }, heading: game.state.player.heading, source: 'debug', force: true });
      const bearing = ctx.util.bearingTo(best.camera.x, best.camera.z, best.x, best.z);
      ctx.systems.flight.resetTo({ x: best.camera.x, y: best.camera.y - 30, z: best.camera.z, heading: bearing + 90 });
      const framed = ctx.systems.camera.setFreeCameraPose({ position: best.camera, target: best.target });
      return { id, framed, slope: Math.round(best.score), water: best.base === waterLevel };
    },
    /**
     * Resolves once the GPU memory counts have held still for 60 frames (terrain chunks streamed
     * in), or after timeoutMs, so the dispose baseline measures the engine alone.
     */
    settle(timeoutMs = 20000) {
      const memory = ctx.renderer.info.memory;
      const start = performance.now();
      let last = '';
      let still = 0;
      return new Promise((resolve) => {
        const tick = () => {
          const counts = `${memory.geometries}/${memory.textures}/${memory.attributes}`;
          still = counts === last ? still + 1 : 0;
          last = counts;
          const waitedMs = Math.round(performance.now() - start);
          if (still >= 60 || waitedMs > timeoutMs) {
            resolve(JSON.stringify({ settled: still >= 60, waitedMs, counts }));
            return;
          }
          requestAnimationFrame(tick);
        };
        requestAnimationFrame(tick);
      });
    },
    sun(elevation) {
      ctx.systems.sky.setDayTime(ctx.util.dayTimeForSunElevation(elevation, true), { transition: 0 });
    },
  };
  // Photo mode frames the shots with the free camera; the simulation keeps running (photo mode
  // pauses it by default), so the emitters emit and the particles move.
  ctx.setPhotoMode(true);
  game.state.paused = false;
  return window.__dwCheck('setup: engine registered, presets added', true, JSON.stringify({ backend: ctx.backend, compute: engine.stats().compute, presets: window.__dwEm.ids }));
})()

