(() => {
  const em = window.__dwEm;
  const { ctx, state } = window.DRIFTWING;
  const spawns = ctx.systems.spawns;
  const engine = em.engine;
  em.idleFrameMs = Math.round(((performance.now() - em.idle.time) / Math.max(1, state.frame - em.idle.frame)) * 100) / 100;
  const original = engine.update;
  const meter = { cpu: 0, calls: 0, frame: state.frame, time: performance.now() };
  engine.update = function measuredUpdate(instance, dt, engineCtx) {
    const start = performance.now();
    original.call(engine, instance, dt, engineCtx);
    meter.cpu += performance.now() - start;
    meter.calls++;
  };
  em.meter = meter;
  em.restoreUpdate = () => { engine.update = original; };
  em.cycle = [
    spawns.forceSpawn('emVolcano', { distance: 1800 }),
    spawns.forceSpawn('emGeyser', { distance: 450 }),
    spawns.forceSpawn('emMist', { distance: 500 }),
    spawns.forceSpawn('emDustRing', { distance: 700 }),
    spawns.forceSpawn('emSpout', { distance: 300 }),
    spawns.forceSpawn('emLanterns', { distance: 900 }),
  ];
  return JSON.stringify({ cycle: em.cycle });
})()

