    instances: stats.instances,
    cpuMsPerFrame: Math.round((meter.cpu / frames) * 1000) / 1000,
    cpuMsPerInstance: Math.round((meter.cpu / Math.max(1, meter.calls)) * 1000) / 1000,
    idleFrameMs: em.idleFrameMs,
    frameMs: Math.round(((performance.now() - meter.time) / frames) * 100) / 100,
  };
  em.restoreUpdate();
  const ok = stats.instances === 7 && stats.particles > 15000 && stats.drawCalls === 2;
  return window.__dwCheck('seven emitters in two draw calls', ok, JSON.stringify({ stats, cost }));
})()

(() => {
  const em = window.__dwEm;
  for (const id of em.cycle) if (id) window.DRIFTWING.ctx.systems.spawns.deactivate(id, 'test');
  return 'all ended';
})()

(() => {
  window.DRIFTWING.state.paused = true;
  return window.__dwEm.settle();
})()

(() => {
  const em = window.__dwEm;
  const { ctx, state } = window.DRIFTWING;
  state.paused = true;
  em.baseline = em.snapshot();
  const spawns = ctx.systems.spawns;
  em.cycle = em.ids.map((id) => spawns.forceSpawn(id, { distance: id === 'emVolcano' ? 1800 : 600 }));
  return JSON.stringify({ baseline: em.baseline, cycle: em.cycle });
})()

(() => {
  const em = window.__dwEm;
  em.peak = { ...em.snapshot(), stats: em.engine.stats() };
  for (const id of em.cycle) if (id) window.DRIFTWING.ctx.systems.spawns.deactivate(id, 'test');
  return JSON.stringify({ peak: em.peak });
})()

(() => {
  const em = window.__dwEm;
  const { ctx } = window.DRIFTWING;
  const spawnStats = ctx.systems.spawns.getStats();
  const now = em.snapshot();
  const stats = em.engine.stats();
  const baseline = em.baseline;
  const ok = Object.keys(baseline).every((key) => now[key] === baseline[key])
    && stats.instances === 0 && stats.particles === 0 && stats.lights === 0
    && stats.pages.alpha.used === 0 && stats.pages.additive.used === 0
    && spawnStats.leaks.windSources === 0 && spawnStats.leaks.lights === 0;
  return window.__dwCheck('dispose returns GPU memory, pages, lights, wind sources and modifiers to the baseline', ok, JSON.stringify({ baseline, peak: em.peak, now, stats, leaks: spawnStats.leaks }));
})()

(() => {
  const { ctx } = window.DRIFTWING;
  for (const id of window.__dwEm.ids) ctx.systems.spawns.debug.removePreset(id);
  ctx.systems.sky.setDayTime(ctx.util.dayTimeForSunElevation(ctx.CONFIG.START_SUN_ELEVATION_DEG, true), { transition: 0 });
  ctx.setPhotoMode(false);
  return 'test presets removed, flying again';
})()
